UPDATE public.telegram_starts SET seo_title = COALESCE(NULLIF(seo_title, ''), title) WHERE seo_title IS NULL OR seo_title = ''; UPDATE public.telegram_starts SET seo_description = COALESCE(NULLIF(seo_description, ''), LEFT(description, 160)) WHERE seo_description IS NULL OR seo_description = ''; ALTER TABLE public.telegram_starts ALTER COLUMN seo_title SET NOT NULL, ALTER COLUMN seo_title SET DEFAULT '', ALTER COLUMN seo_description SET NOT NULL, ALTER COLUMN seo_description SET DEFAULT '';